import {currentSchool,schoolDataKey} from '../core/schools.js';
import {parseGrades} from '../core/grades.js';
const $=s=>document.querySelector(s),E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY=schoolDataKey('course-compass.grades.v1'),PREF=schoolDataKey('course-compass.user.v1'),PROFILE=schoolDataKey('course-compass.profile.v1');
export function setupUser({getSettings,notify,setView}){
 function openSchool(){const school=currentSchool();if(school.adapter==='manual'&&!school.loginUrl){document.querySelector('[data-action="table"]').click();return;}if(window.CourseCompass?.openPortal){window.CourseCompass.openPortal();return;}if(school.loginUrl)window.open(school.loginUrl,'_blank','noopener,noreferrer');else notify('此模式无需登录：在菜单选择通用表格导入');}

 let identity=null;try{identity=JSON.parse(localStorage.getItem(PROFILE)||'null');}catch{}
 let connection={state:'unknown',reason:''};
 let cache={},selected={year:String(new Date(getSettings().startDate+'T12:00:00').getFullYear()),term:'3'};
 try{cache=JSON.parse(localStorage.getItem(KEY)||'{}');}catch{}try{selected={...selected,...JSON.parse(localStorage.getItem(PREF)||'{}')};}catch{}
 if(!/^20\d{2}$/.test(selected.year))selected.year='2026';if(!['3','12','16'].includes(selected.term))selected.term='3';
 $('#grade-year').value=selected.year;$('#grade-term').value=selected.term;
 function render(){const stored=cache[selected.year+'-'+selected.term],entry=stored&&(stored.courses?.length||stored.verified===true)?stored:null,native=!!window.CourseCompass?.openPortal,last=localStorage.getItem('course-compass.lastImport'),latest=Object.values(cache).sort((a,b)=>String(b.updatedAt).localeCompare(String(a.updatedAt)))[0],profile=identity||(entry?.profile?.name||entry?.profile?.studentId?entry.profile:latest?.profile);
 $('#user-name').textContent=profile?.name||'我的校园';$('#user-student').textContent=profile?.studentId?'学号 '+profile.studentId:'尚未读取姓名与学号';$('#profile-login').textContent=profile?.name?'更新姓名与学号':'登录并读取姓名与学号';$('#user-avatar').textContent=profile?.name?.slice(0,1)||'我';
 $('#connection-state').dataset.state=connection.state;$('#connection-state').textContent=native?(connection.reason||'点下方按钮登录学校官方门户，登录状态以学校页面为准。'):'网页版可查看离线数据；使用通用表格导入，或在 Android 应用连接已适配学校。';$('#connection-badge').textContent=!native?'网页版':connection.state==='ready'?'已识别查询':connection.state==='failed'||connection.state==='blocked'?'需重试':connection.state==='login'?'需登录':'官方登录';$('#user-sync-time').textContent=last?'课表确认更新于 '+new Date(last).toLocaleString('zh-CN'):'尚未确认导入教务课表';
 $('#grade-badge').textContent=entry?(entry.coverage==='loaded-page'?'页面快照 · 离线可看':'已缓存 · 离线可看'):'未读取';$('#grade-semester').textContent=`本地查看：${selected.year}–${Number(selected.year)+1} 学年 · ${selected.term==='3'?'第一学期':selected.term==='12'?'第二学期':'第三学期'}`;
 $('#user-grade-time').textContent=entry?'成绩读取于 '+new Date(entry.updatedAt).toLocaleString('zh-CN'):'尚未读取所选学期成绩';
 $('#gpa-label').textContent=entry?.coverage==='loaded-page'?'已载入课程参考绩点':'学分加权参考绩点';const summary=entry?.summary;$('#user-gpa').textContent=summary?.gpa!=null?summary.gpa.toFixed(2):'—';$('#user-credits').textContent=summary?String(Number(summary.credits.toFixed(2))):'—';
 $('#grade-note').textContent=!entry?(stored?'上一版未核实空成绩结果，请重新从学校页面查询。':'尚未读取成绩。同步时在学校页面选择学期，课间会自动跟随；这里可以切换查看已保存的学期。'):!entry.courses.length?'学校的有效成绩查询返回 0 条记录。可切换已结束的学期；如果官网已有成绩，请重新查询并复制读取诊断。':`${entry.coverage==='loaded-page'?'来自学校页面已加载的 '+entry.courses.length+' 门课程，可能不含尚未加载或其他分页；不是学校官方总绩点。':''}参考绩点 = Σ(学分×学校返回绩点) ÷ Σ学分，共 ${summary.count} 门参与。${summary.missing?'有 '+summary.missing+' 门缺少学分或绩点，未参与计算。':''}${summary.duplicates?'存在同课程多条成绩，当前包含全部返回记录。':''}学校重修、免修等规则可能不同，以学校正式统计为准。`;
 $('#grade-list').innerHTML=entry?.courses.length?entry.courses.map(c=>`<div class="grade-row"><div><b>${E(c.name)}</b><small>${c.credit==null?'学分未返回':E(c.credit)+' 学分'} · ${c.point==null?'绩点未返回':'绩点 '+E(c.point)}${c.nature?' · '+E(c.nature):''}</small></div><strong>${E(c.score||'未发布')}</strong></div>`).join(''):'<div class="user-empty">'+(entry?'此学期返回 0 条成绩':'还没有成绩数据')+'</div>';
 $('#read-grades').disabled=currentSchool().adapter!=='zfsoft';if(currentSchool().adapter!=='zfsoft'){$('#grade-note').textContent='此学校尚未接入成绩适配器；通用课表功能可正常使用。';$('#connection-state').textContent='当前使用通用导入。可从菜单导入表格、CSV或课程JSON；自动教务同步需对应学校适配器。';}$('#previous-grades').hidden=!!entry?.courses.length;
 }
 function choose(){selected={year:$('#grade-year').value,term:$('#grade-term').value};try{localStorage.setItem(PREF,JSON.stringify(selected));}catch{notify('学期选择未能保存');}render();}
 $('#grade-year').onchange=choose;$('#grade-term').onchange=choose;
 $('#read-grades').onclick=()=>{if(currentSchool().adapter!=='zfsoft'){notify('此学校尚未接入成绩适配器；课表可使用通用导入');return;}choose();if(!/^20\d{2}$/.test(selected.year)){notify('请填写有效学年，例如2026');return;}if(window.CourseCompass?.openGrades)window.CourseCompass.openGrades(Number(selected.year),Number(selected.term));else notify('请使用 Android 应用，在学校官方页面查询成绩');};
 $('#previous-grades').onclick=()=>{const year=Number(selected.year),term=selected.term;$('#grade-year').value=String(term==='3'?year-1:year);$('#grade-term').value=term==='3'?'12':term==='12'?'3':'12';choose();$('#read-grades').click();};
 window.onSchoolStatus=(state,reason)=>{connection={state,reason:String(reason||'')};render();};
 $('#profile-login').onclick=()=>{if(window.CourseCompass?.openProfile)window.CourseCompass.openProfile();else if(window.CourseCompass?.openPortal)openSchool();else notify('请使用 Android 版登录学校并打开个人信息');};
 window.receiveSchoolProfile=value=>{try{const p=typeof value==='string'?JSON.parse(value):value;if(!p||!String(p.name||'').trim()||! /^[A-Za-z0-9]{6,24}$/.test(String(p.studentId||'')))return {ok:false};identity={name:String(p.name).trim().slice(0,60),studentId:String(p.studentId),updatedAt:new Date().toISOString()};localStorage.setItem(PROFILE,JSON.stringify(identity));render();return {ok:true};}catch{return {ok:false};}};
 $('#user-login').onclick=openSchool;
 $('#user-sync').onclick=()=>{if(currentSchool().adapter==='manual'){document.querySelector('[data-action="table"]').click();return;}if(window.CourseCompass?.syncPortal)window.CourseCompass.syncPortal();else notify('教务刷新需要 Android 版；网页版可导入 PDF / JSON');};
 window.receiveSchoolGrades=text=>{try{const entry=parseGrades(typeof text==='string'?JSON.parse(text):text);const existing=cache[entry.year+'-'+entry.term];if(entry.coverage==='loaded-page'&&!window.confirm(entry.year+'–'+(Number(entry.year)+1)+' 学年 · '+(entry.term==='3'?'第一学期':entry.term==='12'?'第二学期':'第三学期')+'\n已从学校页面读取 '+entry.courses.length+' 门课程：\n'+entry.courses.slice(0,10).map(c=>c.name+'：'+c.score+' / '+c.credit+' 学分 / 绩点 '+c.point).join('\n')+(entry.courses.length>10?'\n另有 '+(entry.courses.length-10)+' 门':'')+'\n\n仅包含学校页面已加载的课程；有更多课程时，请在官网加载完成后再次读取。确认保存并更新这个学期的本地成绩？'))return {ok:false,error:'已取消保存，原成绩已保留'};if(!entry.courses.length&&existing?.courses?.length&&!window.confirm('学校本次返回 0 条成绩，但本机已保存 '+existing.courses.length+' 条。是否用本次空结果替换？取消可保留原成绩。'))return {ok:false,error:'已保留原有成绩。请确认学校查询学期后重试。'};const next={...cache,[entry.year+'-'+entry.term]:entry};localStorage.setItem(KEY,JSON.stringify(next));cache=next;selected={year:entry.year,term:entry.term};localStorage.setItem(PREF,JSON.stringify(selected));$('#grade-year').value=entry.year;$('#grade-term').value=entry.term;setView('user');render();connection={state:'ready',reason:'已成功查询学校成绩；下次同步时会重新检查学校会话。'};render();notify(entry.courses.length?'学期成绩已更新':'此学期查询成功，返回 0 条成绩');return {ok:true,count:entry.courses.length};}catch(error){notify(error.message);return {ok:false,error:error.message};}};
 render();return {render};
}
